// ───────────────────────────── segmentos medulares
const SEG = {
  C1: ['—', 'Músculos suboccipitales (nervio suboccipital)', ''], C2: ['Occipucio (nervio occipital mayor)', 'Flexión y rotación del cuello', ''],
  C3: ['Cuello y fosa supraclavicular', 'Diafragma (C3–C5), trapecio', ''], C4: ['Hombro (región acromioclavicular)', 'Diafragma (C3–C5)', ''],
  C5: ['Cara lateral del brazo', 'Deltoides (abducción del hombro), bíceps', 'Bicipital (C5–C6)'], C6: ['Antebrazo lateral y pulgar', 'Extensores de la muñeca, bíceps, braquiorradial', 'Bicipital y braquiorradial (C5–C6)'],
  C7: ['Dedo medio', 'Tríceps (extensión del codo), flexores de la muñeca, extensores de los dedos', 'Tricipital (C7)'], C8: ['Dedo meñique y borde cubital de la mano', 'Flexores de los dedos (flexor profundo)', ''],
  T1: ['Cara medial del antebrazo', 'Interóseos (abducción de los dedos)', ''], T2: ['Axila y cara medial del brazo', 'Intercostales', ''], T3: ['Tercer espacio intercostal', 'Intercostales', ''],
  T4: ['Nivel de los pezones', 'Intercostales', ''], T5: ['Bajo los pezones', 'Intercostales', ''], T6: ['Apófisis xifoides', 'Intercostales, abdominales superiores', ''],
  T7: ['Epigastrio', 'Abdominales superiores', 'Cutáneo abdominal superior (T7–T9)'], T8: ['Reborde costal', 'Abdominales', 'Cutáneo abdominal superior'], T9: ['Sobre el ombligo', 'Abdominales', 'Cutáneo abdominal medio (T9–T11)'],
  T10: ['Ombligo', 'Abdominales', 'Cutáneo abdominal medio'], T11: ['Bajo el ombligo', 'Abdominales inferiores', 'Cutáneo abdominal inferior (T11–L1)'], T12: ['Región suprapúbica e inguinal', 'Abdominales inferiores', 'Cutáneo abdominal inferior'],
  L1: ['Ingle y parte alta del muslo', 'Flexión de la cadera (iliopsoas, L1–L3)', 'Cremastérico (L1–L2)'], L2: ['Cara anterior del muslo', 'Flexión de la cadera (iliopsoas), aductores', 'Cremastérico (L1–L2)'],
  L3: ['Cara anterior del muslo y medial de la rodilla', 'Extensión de la rodilla (cuádriceps)', 'Rotuliano (L3–L4)'], L4: ['Cara medial de la pierna y maléolo medial', 'Dorsiflexión del pie (tibial anterior), cuádriceps', 'Rotuliano (L3–L4)'],
  L5: ['Cara lateral de la pierna, dorso del pie y hallux', 'Extensión del hallux, dorsiflexión, abducción de la cadera (glúteo medio)', '(isquiotibial medial)'], S1: ['Borde lateral del pie, meñique y planta', 'Flexión plantar (gastrocnemio y sóleo), glúteo mayor', 'Aquíleo (S1)'],
  S2: ['Cara posterior del muslo y fosa poplítea', 'Flexores de los dedos del pie, esfínteres', ''], S3: ['Región glútea medial («silla de montar»)', 'Esfínteres anal y uretral externos (núcleo de Onuf, S2–S4)', 'Bulbocavernoso (S2–S4)'],
  S4: ['Región perianal', 'Esfínteres, suelo pélvico', 'Anal (S4–S5)'], S5: ['Región perianal', 'Suelo pélvico', 'Anal (S4–S5)'],
};
const NIV = { C: 'cervical', T: 'torácico', L: 'lumbar', S: 'sacro' };
for (const [id, [der, mio, ref]] of Object.entries(SEG)) {
  const r = id[0], k = +id.slice(1);
  const extra = [];
  if ((r === 'C' && k >= 5) || id === 'T1') extra.push('Forma parte del engrosamiento cervical (C5–T1), con astas anteriores voluminosas para el plexo braquial.');
  if ((r === 'L' && k >= 2) || (r === 'S' && k <= 3)) extra.push('Forma parte del engrosamiento lumbosacro (L2–S3), origen de los plexos lumbar y sacro.');
  if (r === 'T' || id === 'L1' || id === 'L2') extra.push('Su asta lateral (columna intermediolateral, T1–L2) contiene las neuronas preganglionares simpáticas.');
  if (r === 'S' && k >= 2 && k <= 4) extra.push('Contiene las neuronas preganglionares parasimpáticas sacras (S2–S4): micción, defecación y erección.');
  if (id === 'C8' || id === 'T1' || id === 'T2') extra.push('Centro cilioespinal de Budge (C8–T2): origen de la inervación simpática del dilatador de la pupila.');
  if (r === 'S') extra.push('Los segmentos sacros forman el cono medular, a la altura de las vértebras T12–L1.');
  CUERPO['me_' + id] = {
    n: `Médula espinal, segmento ${id}`, la: `Medulla spinalis, segmentum ${NIV[r]} ${k}`, g: 'medula.' + r, s: 'somato', a: 'espinal',
    d: `Segmento medular ${NIV[r]} ${k}; de él nacen las raíces anterior (motora) y posterior (sensitiva) del nervio espinal ${id}. ${extra.join(' ')}`,
    f: [`Dermatoma: ${der}`, `Miotoma: ${mio}`, ...(ref ? [`Reflejo: ${ref}`] : []), 'Sustancia gris en «H»: asta posterior (láminas I–VI, sensitiva), zona intermedia (VII) y asta anterior (VIII–IX, motoneuronas α y γ)', 'Sustancia blanca: columnas dorsales (tacto fino y propiocepción ipsilaterales), cordón lateral (tracto corticoespinal lateral y espinocerebelosos) y sistema anterolateral (dolor y temperatura contralaterales)'],
    c: 'Ascendentes: fascículos grácil y cuneiforme, tractos espinotalámico y espinocerebelosos. Descendentes: corticoespinales lateral y anterior, rubroespinal, reticuloespinales, vestibuloespinales, tectoespinal y fibras hipotalamoespinales.',
    cl: 'Hemisección (Brown-Séquard): parálisis y pérdida de tacto fino y propiocepción ipsilaterales, y de dolor y temperatura contralaterales (desde 1–2 segmentos más abajo). Sección completa: choque medular seguido de espasticidad. Síndrome centromedular (siringomielia): pérdida disociada «en capa». ELA: asta anterior y vía corticoespinal. Déficit de B12 y tabes dorsal: columnas dorsales.'
  };
}
